#!/usr/bin/env python3
from __future__ import annotations

import argparse
import base64
import datetime as dt
import importlib.util
import os
import py_compile
import shutil
import subprocess
import sys
from pathlib import Path

VERSION = "0.5.0"
MODIFIED_B64 = {'backend/app/api/v1/endpoints/lab_service_api.py': {'old': '', 'new': ''}, 'backend/app/api/v1/endpoints/sampling_geometry_api.py': {'old': '', 'new': ''}, 'backend/app/services/vision_labs/service/runtime.py': {'old': '', 'new': ''}, 'frontend/src/Pages/SamplingGeometryLabPage.tsx': {'old': '', 'new': ''}, 'frontend/src/api/samplingGeometryApi.ts': {'old': '', 'new': ''}, 'frontend/tools/generate_llm_context_map.py': {'old': '', 'new': ''}}
CREATED_B64 = {'backend/app/services/vision_labs/sampling_geometry/program.py': '', 'backend/app/services/vision_labs/sampling_geometry/program_runtime.py': '', 'backend/tests/vision_labs/sampling_geometry/test_sampling_program_v0500.py': '', 'frontend/docs/llm_context/updates/v0500_sampling_program_global_local.md': '', 'frontend/src/components/VisionLabs/SamplingProgram/SamplingConceptHelpModal.tsx': '', 'frontend/src/components/VisionLabs/SamplingProgram/SamplingMethodEditor.tsx': '', 'frontend/src/components/VisionLabs/SamplingProgram/SamplingMethodLibrary.tsx': '', 'frontend/src/components/VisionLabs/SamplingProgram/SamplingOutputShapeDesigner.tsx': '', 'frontend/src/components/VisionLabs/SamplingProgram/SamplingProgramCanvas.tsx': '', 'frontend/src/components/VisionLabs/SamplingProgram/SamplingStructurePanel.tsx': '', 'frontend/src/components/VisionLabs/SamplingProgram/types.ts': '', 'frontend/src/components/VisionLabs/SamplingProgram/useSamplingProgramController.ts': ''}
MODIFIED = {k: {"old": base64.b64decode(v["old"]).decode("utf-8"), "new": base64.b64decode(v["new"]).decode("utf-8")} for k, v in MODIFIED_B64.items()}
CREATED = {k: base64.b64decode(v).decode("utf-8") for k, v in CREATED_B64.items()}


def resolve_roots(frontend_arg=None, backend_arg=None):
    cwd = Path.cwd().resolve()
    fes, bes = [], []
    if frontend_arg:
        fes.append(Path(frontend_arg).expanduser().resolve())
    if backend_arg:
        bes.append(Path(backend_arg).expanduser().resolve())
    fes += [cwd, cwd / "LambdaVisionSuper", cwd.parent / "LambdaVisionSuper"]
    bes += [cwd, cwd / "LambdaVisionSuperBackEnd", cwd.parent / "LambdaVisionSuperBackEnd"]
    fe = next((p for p in fes if (p / "src/App.tsx").exists() and (p / "src/Pages/SamplingGeometryLabPage.tsx").exists()), None)
    be = next((p for p in bes if (p / "app/main.py").exists() and (p / "app/services/vision_labs/sampling_geometry").exists()), None)
    if fe is None:
        raise RuntimeError("Cannot locate LambdaVisionSuper frontend; use --frontend PATH")
    if be is None:
        raise RuntimeError("Cannot locate LambdaVisionSuperBackEnd; use --backend PATH")
    return fe, be


def path_for(fe, be, virtual):
    if virtual.startswith("frontend/"):
        return fe / virtual[len("frontend/"):]
    if virtual.startswith("backend/"):
        return be / virtual[len("backend/"):]
    raise ValueError(virtual)


def state_modified(path, old, new):
    if not path.exists():
        return "MISSING"
    current = path.read_text(encoding="utf-8")
    if current == new:
        return "OK"
    if current == old:
        return "UPDATE"
    return "CONFLICT"


def state_created(path, desired):
    if not path.exists():
        return "CREATE"
    return "OK" if path.read_text(encoding="utf-8") == desired else "CONFLICT"


def scan(fe, be):
    print("=" * 98)
    print("SAMPLING LAB V0.5.0 — GLOBAL / LOCAL SAMPLING PROGRAM")
    print("=" * 98)
    print(f"Frontend : {fe}")
    print(f"Backend  : {be}\n")
    conflicts = 0
    for virtual, payload in MODIFIED.items():
        state = state_modified(path_for(fe, be, virtual), payload["old"], payload["new"])
        print(f"  [{state:10}] {virtual}")
        conflicts += state in {"CONFLICT", "MISSING"}
    for virtual, desired in CREATED.items():
        state = state_created(path_for(fe, be, virtual), desired)
        print(f"  [{state:10}] {virtual}")
        conflicts += state == "CONFLICT"
    print("\nNew editor/runtime contract:")
    print("  Image -> GLOBAL or LOCAL domain -> method -> placement -> channel -> measure -> output shape")
    print("  GLOBAL: whole-image Histogram / Statistics / Rays / Cross / Rings")
    print("  LOCAL : Patch Grid; one reusable method recipe is repeated on each patch")
    print("  Cross/Rings: center/base mode or auto-arranged center grid")
    print("  Output Shape Designer: vector / patch matrix / spatial tensor")
    print("  FFT/frequency transforms are removed from the v0.5 editor/catalog scope")
    print("  Legacy v0.1-v0.4 runtime remains for old deployed services")
    print("  LLM context generator + v0.5 handoff MD are included")
    if conflicts:
        print(f"\n[WARN] {conflicts} conflict/base issue(s); apply will stop safely.")
    return 0


def preflight(fe, be):
    errors = []
    for virtual, payload in MODIFIED.items():
        state = state_modified(path_for(fe, be, virtual), payload["old"], payload["new"])
        if state not in {"UPDATE", "OK"}:
            errors.append(f"{virtual}: {state}")
    for virtual, desired in CREATED.items():
        state = state_created(path_for(fe, be, virtual), desired)
        if state not in {"CREATE", "OK"}:
            errors.append(f"{virtual}: {state}")
    if "/labs/sampling-geometry" not in (fe / "src/App.tsx").read_text(encoding="utf-8"):
        errors.append("frontend/src/App.tsx: Sampling LAB route missing")
    if "sampling_geometry_api" not in (be / "app/api/v1/api.py").read_text(encoding="utf-8"):
        errors.append("backend/app/api/v1/api.py: Sampling API router missing")
    if errors:
        raise RuntimeError("Safe update stopped:\n  - " + "\n  - ".join(errors))


def backup(fe, be, paths):
    stamp = dt.datetime.now().strftime("%Y%m%d_%H%M%S")
    root = fe / ".lambda_updater_backups" / f"sampling_lab_v0500_{stamp}"
    root.mkdir(parents=True, exist_ok=True)
    for path in paths:
        if not path.exists():
            continue
        try:
            rel = path.relative_to(fe)
            dest = root / "frontend" / rel
        except ValueError:
            rel = path.relative_to(be)
            dest = root / "backend" / rel
        dest.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(path, dest)
    return root


def regenerate_context(fe, be):
    generator = fe / "tools/generate_llm_context_map.py"
    if not generator.exists():
        print("[SKIP] context generator missing")
        return
    cmd = [sys.executable, str(generator), "--frontend", str(fe), "--backend", str(be)]
    if "--output-dir" in generator.read_text(encoding="utf-8"):
        cmd += ["--output-dir", str(fe / "docs/llm_context")]
    proc = subprocess.run(cmd, cwd=str(fe), text=True, capture_output=True)
    if proc.returncode:
        raise RuntimeError("Context regeneration failed:\n" + (proc.stdout + "\n" + proc.stderr).strip())
    if proc.stdout.strip():
        print(proc.stdout.strip())


def apply(fe, be):
    preflight(fe, be)
    targets = [path_for(fe, be, v) for v in list(MODIFIED) + list(CREATED)]
    backup_root = backup(fe, be, targets)
    for virtual, payload in MODIFIED.items():
        path = path_for(fe, be, virtual)
        if path.read_text(encoding="utf-8") != payload["new"]:
            path.write_text(payload["new"], encoding="utf-8")
            print("[WRITE]", virtual)
    for virtual, desired in CREATED.items():
        path = path_for(fe, be, virtual)
        path.parent.mkdir(parents=True, exist_ok=True)
        if not path.exists() or path.read_text(encoding="utf-8") != desired:
            path.write_text(desired, encoding="utf-8")
            print("[WRITE]", virtual)
    print("[INFO] Regenerating LLM context docs...")
    regenerate_context(fe, be)
    print("[OK] Backup:", backup_root)
    print("Run verify next.")
    return 0


def python_syntax(be):
    failures, count = [], 0
    for virtual in list(MODIFIED) + list(CREATED):
        if virtual.startswith("backend/") and virtual.endswith(".py"):
            count += 1
            try:
                py_compile.compile(str(path_for(Path("/unused"), be, virtual)), doraise=True)
            except Exception as exc:
                failures.append(f"{virtual}: {exc}")
    return count, failures


def typescript_transpile(fe):
    files = [path_for(fe, Path("/unused"), v) for v in list(MODIFIED) + list(CREATED) if v.startswith("frontend/") and v.endswith((".ts", ".tsx"))]
    code = 'const fs=require("fs"),ts=require("typescript");let bad=false;for(const f of process.argv.slice(1)){const s=fs.readFileSync(f,"utf8");const r=ts.transpileModule(s,{fileName:f,reportDiagnostics:true,compilerOptions:{jsx:ts.JsxEmit.ReactJSX,target:ts.ScriptTarget.ES2020,module:ts.ModuleKind.ESNext}});const es=(r.diagnostics||[]).filter(d=>d.category===ts.DiagnosticCategory.Error);if(es.length){bad=true;console.error("TS_ERROR",f);for(const e of es)console.error(ts.flattenDiagnosticMessageText(e.messageText,"\\n"));}}process.exit(bad?1:0);'
    env = dict(os.environ)
    npm_root = subprocess.run(["npm", "root", "-g"], text=True, capture_output=True)
    if npm_root.returncode == 0 and npm_root.stdout.strip():
        env["NODE_PATH"] = npm_root.stdout.strip() + (os.pathsep + env["NODE_PATH"] if env.get("NODE_PATH") else "")
    return subprocess.run(["node", "-e", code, *map(str, files)], cwd=str(fe), env=env, text=True, capture_output=True)


def backend_smoke(be):
    code = '''
import cv2, numpy as np
from app.services.vision_labs.image.types import ImageFrame, ColorSpace
from app.services.vision_labs.sampling_geometry.program import SamplingProgramDefinition, sampling_program_catalog
from app.services.vision_labs.sampling_geometry.program_runtime import SamplingProgramRuntime
img=np.zeros((120,180,3),np.uint8);img[...,1]=np.tile(np.arange(180,dtype=np.uint8),(120,1));cv2.circle(img,(90,60),28,(220,80,40),-1)
frame=ImageFrame(img,ColorSpace.BGR)
p=SamplingProgramDefinition(**{"global_domain":{"methods":[{"id":"hist","kind":"histogram","channels":["gray"],"measures":["histogram"],"histogram_bins":8},{"id":"rays","kind":"rays","channels":["gray","h"],"measures":["profile","mean","std"],"sample_count":16,"parameters":{"axis":"both","ray_count":2}}]},"local_domain":{"grid":{"rows":2,"cols":3},"methods":[{"id":"cross","kind":"cross","channels":["gray"],"measures":["profile","mean"],"placement":{"mode":"auto_grid","rows":2,"cols":2},"sample_count":8,"parameters":{"length_ratio":0.8}},{"id":"stats","kind":"statistics","channels":["r","g","b"],"measures":["mean","std"]}]},"output_shape":{"local_layout":"spatial_tensor","local_order":"patch_major"}})
r=SamplingProgramRuntime(p).run(frame)
assert r.local_data.shape[:2]==(2,3);assert len(r.local_patch_blocks)==6;assert r.global_data.shape[0]>0
assert {x["kind"] for x in sampling_program_catalog()}=={"histogram","statistics","rays","cross","rings"}
p.output_shape.local_order="feature_major";r2=SamplingProgramRuntime(p).run(frame);assert r2.local_data.shape[1:]==(2,3)
print("SAMPLING_V0500_SMOKE_OK",r.global_data.shape,r.local_data.shape,r2.local_data.shape,r.combined_data.shape)
'''
    return subprocess.run([sys.executable, "-c", code], cwd=str(be), text=True, capture_output=True)


def verify(fe, be, skip_build=False):
    print("=" * 98)
    print("VERIFY SAMPLING LAB V0.5.0")
    print("=" * 98)
    failures = 0
    page = (fe / "src/Pages/SamplingGeometryLabPage.tsx").read_text(encoding="utf-8")
    program = (be / "app/services/vision_labs/sampling_geometry/program.py").read_text(encoding="utf-8")
    runtime = (be / "app/services/vision_labs/sampling_geometry/program_runtime.py").read_text(encoding="utf-8")
    service = (be / "app/services/vision_labs/service/runtime.py").read_text(encoding="utf-8")
    labapi = (be / "app/api/v1/endpoints/lab_service_api.py").read_text(encoding="utf-8")
    generator = (fe / "tools/generate_llm_context_map.py").read_text(encoding="utf-8")
    checks = [
        ("Global/Local Sampling editor", "SamplingMethodLibrary" in page and "SamplingStructurePanel" in page and "Spectral / Statistics" not in page),
        ("SamplingProgram domain model", "class SamplingProgramDefinition" in program and "global_domain" in program and "local_domain" in program),
        ("FFT removed from v0.5 catalog", '"fft"' not in program and "sampling_program_catalog" in program),
        ("Local Patch Grid runtime", "_patch_frame" in runtime and "matrix.reshape(rows,cols,max_dim)" in runtime),
        ("Center/auto-grid placement", "auto_grid" in program and "_grid_centers" in runtime),
        ("Output Shape Designer", (fe / "src/components/VisionLabs/SamplingProgram/SamplingOutputShapeDesigner.tsx").exists()),
        ("Image-grounded channel teaching", "channelPreview" in (fe / "src/components/VisionLabs/SamplingProgram/useSamplingProgramController.ts").read_text(encoding="utf-8")),
        ("Sampling service adapter v1", "sampling_program_v1" in service and "sampling_program_v1" in labapi and "composed_data" in labapi),
        ("Legacy Sampling adapter preserved", "Backward compatibility for v0.1-v0.4" in service and "SamplingPipelineDefinition" in service),
        ("v0.5 context generator", "SamplingProgramRuntime" in generator and "FFT/frequency transforms intentionally out of current editor scope" in generator),
        ("v0.5 MD handoff", (fe / "docs/llm_context/updates/v0500_sampling_program_global_local.md").exists()),
    ]
    for label, ok in checks:
        print(f"[{'OK' if ok else 'FAIL'}] {label}")
        failures += 0 if ok else 1
    count, bad = python_syntax(be)
    if bad:
        print("[FAIL] Python syntax")
        for issue in bad:
            print("  -", issue)
        failures += len(bad)
    else:
        print(f"[OK] Python syntax ({count} changed/new backend files)")
    smoke = backend_smoke(be)
    if smoke.returncode == 0:
        print("[OK] Sampling Program backend smoke")
        print(smoke.stdout.strip())
    else:
        print("[FAIL] Sampling Program backend smoke")
        print((smoke.stdout + "\n" + smoke.stderr).strip())
        failures += 1
    test_paths = [p for p in ["tests/vision_labs/sampling_geometry/test_sampling_program_v0500.py", "tests/vision_labs/sampling_geometry/test_sampling_lab_v0400.py", "tests/vision_labs/sampling_geometry/test_sampling_geometry_lab_v0200.py"] if (be / p).exists()]
    if importlib.util.find_spec("pytest") is None:
        print("[SKIP] pytest unavailable")
    elif test_paths:
        proc = subprocess.run([sys.executable, "-m", "pytest", "-q", *test_paths], cwd=str(be), text=True, capture_output=True)
        if proc.returncode == 0:
            print("[OK] Sampling regression tests")
            print(proc.stdout.strip())
        else:
            print("[FAIL] Sampling regression tests")
            print((proc.stdout + "\n" + proc.stderr).strip())
            failures += 1
    ts = typescript_transpile(fe)
    text = (ts.stdout + "\n" + ts.stderr).strip()
    if ts.returncode == 0:
        print("[OK] TypeScript syntax/transpile")
    elif "Cannot find module" in text or "MODULE_NOT_FOUND" in text:
        print("[SKIP] TypeScript module unavailable")
    else:
        print("[FAIL] TypeScript syntax/transpile")
        print(text)
        failures += 1
    if not skip_build and (fe / "package.json").exists() and (fe / "node_modules").exists():
        proc = subprocess.run(["npm", "run", "build"], cwd=str(fe))
        if proc.returncode == 0:
            print("[OK] Frontend npm build")
        else:
            print("[FAIL] Frontend npm build")
            failures += 1
    else:
        print("[SKIP] Frontend npm build")
    try:
        regenerate_context(fe, be)
        arch = fe / "docs/llm_context/SYSTEM_ARCHITECTURE.md"
        bundles = fe / "docs/llm_context/SYSTEM_CONTEXT_BUNDLES.md"
        ok = arch.exists() and bundles.exists() and "Sampling LAB" in arch.read_text(encoding="utf-8") and "Sampling LAB" in bundles.read_text(encoding="utf-8")
        print(f"[{'OK' if ok else 'FAIL'}] Regenerated LLM context docs")
        failures += 0 if ok else 1
    except Exception as exc:
        print("[FAIL] Context regeneration:", exc)
        failures += 1
    if failures:
        print(f"[FAIL] v0.5.0 verification finished with {failures} issue(s).")
        return 1
    print("[OK] Sampling LAB v0.5.0 Global / Local Sampling Program verified.")
    return 0


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("command", choices=["scan", "apply", "verify"])
    parser.add_argument("--frontend")
    parser.add_argument("--backend")
    parser.add_argument("--skip-build", action="store_true")
    args = parser.parse_args()
    try:
        fe, be = resolve_roots(args.frontend, args.backend)
        if args.command == "scan":
            return scan(fe, be)
        if args.command == "apply":
            return apply(fe, be)
        return verify(fe, be, args.skip_build)
    except Exception as exc:
        print("[ERROR]", exc)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
